arguments.command:
cat > /tmp/stackalloc_nint.cs << 'EOF'
Span<nint> nints = stackalloc nint[4];
nints[0] = 10;
nints[1] = 20;
nints[2] = nint.MaxValue;
nints[3] = nint.MinValue;

Console.WriteLine($"Span<nint> length: {nints.Length}");
Console.WriteLine($"sizeof(nint): {sizeof(nint)} bytes");
for (int i = 0; i < nints.Length; i++)
    Console.WriteLine($"  [{i}] = {nints[i]}");

Span<nuint> nuints = stackalloc nuint[3];
nuints[0] = 42;
nuints[1] = nuint.MaxValue;
nuints[2] = 0;

Console.WriteLine($"\nSpan<nuint> length: {nuints.Length}");
Console.WriteLine($"sizeof(nuint): {sizeof(nuint)} bytes");
for (int i = 0; i < nuints.Length; i++)
    Console.WriteLine($"  [{i}] = {nuints[i]}");
EOF
